            // light: darken towards the fog, on a copy
            const tmp = lit(cv, li, P.fog, a.kind);
            ctx.drawImage(tmp, Math.round(dx), Math.round(dy), Math.round(dw), Math.round(dh));
            if (a.st === 0 && (a.kind === E.KIND.CROWD || a.kind === E.KIND.TARGET)) spriteRects.push({ lane: a.lane, d: a.d, x0: dx / k, y0: dy / k, x1: (dx + dw) / k, y1: (dy + dh) / k });
            // the first catches of the run show where the person on the photo is
            if (a.kind === E.KIND.TARGET && a.st === 0 && p.lv === 0 && p.caught < 2 && z < 12) {
              const ay = dy / k + 14 * gs / k - 12 + Math.sin(time * 9) * 4, ax = footX / k;
              ctx.save(); ctx.setTransform(k, 0, 0, k, 0, 0); ctx.fillStyle = '#ffcf1f'; ctx.strokeStyle = INK; ctx.lineWidth = 3;
              ctx.beginPath(); ctx.moveTo(ax - 11, ay - 12); ctx.lineTo(ax + 11, ay - 12); ctx.lineTo(ax, ay + 4); ctx.closePath(); ctx.stroke(); ctx.fill(); ctx.restore();
            }
