        vig.addColorStop(0, 'rgba(5,3,14,0)'); vig.addColorStop(1, lvI === 5 ? 'rgba(40,10,30,.38)' : 'rgba(5,3,14,.68)');
        ctx.fillStyle = vig; ctx.fillRect(0, 0, W, H);

        if (bullOn && !reducedM) {                 // the Bull Run: the whole frame goes rainbow
          const h0 = Math.floor(time * 240) % 360;
          ctx.globalCompositeOperation = 'overlay'; ctx.globalAlpha = 0.28;
          ctx.fillStyle = 'hsl(' + h0 + ',100%,55%)'; ctx.fillRect(0, 0, W, H);
          ctx.globalCompositeOperation = 'source-over'; ctx.globalAlpha = 1;
          for (let i = 0; i < 16; i++) { ctx.fillStyle = 'hsl(' + ((h0 + i * 24) % 360) + ',100%,62%)'; ctx.fillRect(0, 90 + i * 34, 6, 34); ctx.fillRect(W - 6, 90 + i * 34, 6, 34); }
        }

        /* stains on the lens */
        for (const s of splats) {
          ctx.globalAlpha = Math.max(0, 1 - Math.max(0, s.life - 0.7) / 0.8) * 0.92;
          ctx.fillStyle = s.c;
          const y = s.y + s.life * s.life * 26;
          for (let i = 0; i < 7; i++) {
            const a = (s.seed + i * 2.1), rr = s.r * (0.5 + ((s.seed * (i + 3)) % 7) / 10);
            const qx = Math.round((s.x + Math.cos(a) * s.r) / 4) * 4, qy = Math.round((y + Math.sin(a) * s.r) / 4) * 4;
            ctx.fillRect(qx - rr / 2, qy - rr / 2, rr, rr);
          }
        }
        ctx.globalAlpha = 1;

        drawGull(ctx, time);
        if (gag) drawGag(ctx, k, time);

        /* the phone: the photo of who you are after */
        const shakeP = phoneShake > 0 && !reducedM ? Math.sin(time * 70) * phoneShake * 5 : 0;
        const handBob = reducedM ? 0 : Math.sin(stepPhase * 0.5) * 5, handY = reducedM ? 0 : Math.abs(Math.sin(stepPhase * 0.5)) * 6;
        if (!state.noPhone) drawPhone(ctx, k, p, time, handBob + shakeP, handY);
        if (p && newFace > 0 && !state.finished && p.queue[0] !== undefined) {
          text(ctx, 'NEW FACE', W - 92, H - 240, 14, '#ffcf1f', 'center', 900, 4);
        }
        ctx.setTransform(k, 0, 0, k, 0, 0);

        if (dmBubble && p && !state.ending) drawDm(ctx);
        if (flash > 0 && !reducedM) { ctx.globalAlpha = Math.min(0.85, flash); ctx.fillStyle = flashCol; ctx.fillRect(0, 0, W, H); ctx.globalAlpha = 1; }

